// @FIGURE_CODE_BEGIN
(function () {
  var CW = 600, CH = 780;
  var CXc = 230, CYc = 330, R = 155;
  var BLUE = '#2ea7dd', RED = '#e8484c', INK = '#111', GRAY = '#9aa0a6';
  var SERIF = 'Georgia, "Times New Roman", serif';
  var MONO = 'ui-monospace, Consolas, monospace';
  var D2R = Math.PI / 180;

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, CW, CH);

  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#f8f1fb');
    add.stop(0.55, '#dcbde8');
    add.stop(1, '#b587cb');
  });
  try { grad.from(0.15, 1).to(0.85, 0); } catch (e) { }

  var stat = draw.group();
  var dyn = draw.group();

  function PT(a, r) { return [CXc + r * Math.cos(a), CYc - r * Math.sin(a)]; }
  function fp(p) { return p[0].toFixed(2) + ' ' + p[1].toFixed(2); }
  function arcD(r, a0, a1) {
    var A = PT(a0, r), B = PT(a1, r);
    var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
    var sweep = a1 > a0 ? 0 : 1;
    return 'M' + fp(A) + ' A' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + fp(B);
  }
  function tri(g, x, y, dx, dy, s, color) {
    var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var px = -dy, py = dx;
    var pts = [[x, y],
    [x - dx * s + px * s * 0.42, y - dy * s + py * s * 0.42],
    [x - dx * s - px * s * 0.42, y - dy * s - py * s * 0.42]];
    return g.polygon(pts.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '))
      .fill(color).stroke('none');
  }
  function T(g, content, o) {
    o = o || {};
    var t = (typeof content === 'function') ? g.text(content) : g.text(content);
    t.font({ family: o.family || SERIF, size: o.size || 14, style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal' });
    t.fill(o.color || INK);
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
    return t;
  }
  function place(t, x, y, anchor) {
    var b = t.bbox();
    var dx = anchor === 'middle' ? -b.width / 2 : (anchor === 'end' ? -b.width : 0);
    t.move(x + dx, y - b.height / 2);
    return t;
  }

  /* ───────── static scenery ───────── */
  // axes
  stat.line(50, CYc, 570, CYc).stroke({ color: INK, width: 1.6 });
  tri(stat, 576, CYc, 1, 0, 12, INK);
  stat.line(CXc, 622, CXc, 24).stroke({ color: INK, width: 1.6 });
  tri(stat, CXc, 18, 0, -1, 12, INK);

  // unit circle: long solid arc + two dashed hints on the left
  var circ = stat.path(arcD(R, -150 * D2R, 150 * D2R)).fill('none')
    .stroke({ color: BLUE, width: 4.6, linecap: 'round' });
  stat.path(arcD(R, 158 * D2R, 175 * D2R)).fill('none').stroke({ color: BLUE, width: 4.6, linecap: 'round' });
  stat.path(arcD(R, -175 * D2R, -158 * D2R)).fill('none').stroke({ color: BLUE, width: 4.6, linecap: 'round' });
  circ.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Unit circle: the angle θ is carried to the point (cos θ, sin θ)', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The unit circle', 'Every real number θ is wrapped onto the circle of radius 1 at the point (cos θ, sin θ). Moving θ a little moves that point a little — that is the whole content of continuity for sine and cosine.');
    });

  // caption box
  var capBox = stat.rect(464, 86).move(68, 650).fill('#fff').stroke({ color: '#b3b3b3', width: 1.6 });
  place(T(stat, function (add) {
    add.tspan('As '); add.tspan('x').font({ 'font-style': 'italic' }); add.tspan(' approaches ');
    add.tspan('c').font({ 'font-style': 'italic' }); add.tspan(' the point');
  }, { size: 19 }), 300, 678, 'middle');
  place(T(stat, function (add) {
    add.tspan('P').font({ 'font-style': 'italic' }); add.tspan(' approaches the point ');
    add.tspan('Q').font({ 'font-style': 'italic' }); add.tspan('.');
  }, { size: 19 }), 300, 708, 'middle');
  capBox.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Key insight — click to read', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Why sine and cosine are continuous',
        'Continuity of sine and cosine is nothing more than the geometric fact that nearby angles put you at nearby points on the circle. "P → Q" is literally the pair of statements cos x → cos c and sin x → sin c, and since c was an arbitrary angle, both functions are continuous at every real number.');
    });

  // readout frame
  stat.rect(192, 132).move(398, 390).fill('#fcfcfd').stroke({ color: '#d5d8dc', width: 1.2 }).radius(4);
  place(T(stat, 'values', { size: 11, color: '#8a8f95', family: MONO }), 408, 401, 'start');

  /* ───────── state ───────── */
  var state = { x: 0.5, c: 1.15, approach: 'idle', coords: false };
  var rafId = 0, timerId = 0;

  function render() {
    dyn.clear();
    var x = state.x, c = state.c;
    var P = PT(x, R), Q = PT(c, R);
    var a0 = Math.min(x, c), a1 = Math.max(x, c);

    // sector
    if (a1 - a0 > 0.0015) {
      var A = PT(a0, R), B = PT(a1, R);
      var sec = dyn.path('M' + CXc + ' ' + CYc + ' L' + fp(A) + ' A' + R + ' ' + R + ' 0 0 0 ' + fp(B) + ' Z')
        .fill(grad).opacity(0.92).stroke('none');
      sec.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('Angular gap |x − c| = ' + Math.abs(x - c).toFixed(3) +
            ' rad · chord |PQ| = ' + Math.hypot(P[0] - Q[0], P[1] - Q[1]).toFixed(1) / R * 1 + '', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The shrinking wedge', 'The shaded sector is bounded by the two radii OP and OQ. Its opening angle is exactly |x − c|. Letting x → c collapses the wedge to a single ray, which forces P onto Q.');
        });
    }

    // coordinate projections
    if (state.coords) {
      var dash = { color: GRAY, width: 1.1, dasharray: '4,4' };
      dyn.line(P[0], P[1], P[0], CYc).stroke(dash);
      dyn.line(P[0], P[1], CXc, P[1]).stroke(dash);
      dyn.line(Q[0], Q[1], Q[0], CYc).stroke(dash);
      dyn.line(Q[0], Q[1], CXc, Q[1]).stroke(dash);
