  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, CW, CH);

  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#f8f1fb');
    add.stop(0.55, '#dcbde8');
    add.stop(1, '#b587cb');
  });
  try { grad.from(0.15, 1).to(0.85, 0); } catch (e) { }

  var stat = draw.group();
  var dyn = draw.group();

  function PT(a, r) { return [CXc + r * Math.cos(a), CYc - r * Math.sin(a)]; }
  function fp(p) { return p[0].toFixed(2) + ' ' + p[1].toFixed(2); }
  function arcD(r, a0, a1) {
    var A = PT(a0, r), B = PT(a1, r);
    var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
    var sweep = a1 > a0 ? 0 : 1;
    return 'M' + fp(A) + ' A' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + fp(B);
  }
  function tri(g, x, y, dx, dy, s, color) {
    var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var px = -dy, py = dx;
    var pts = [[x, y],
    [x - dx * s + px * s * 0.42, y - dy * s + py * s * 0.42],
    [x - dx * s - px * s * 0.42, y - dy * s - py * s * 0.42]];
    return g.polygon(pts.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '))
      .fill(color).stroke('none');
  }
  function T(g, content, o) {
    o = o || {};
    var t = (typeof content === 'function') ? g.text(content) : g.text(content);
    t.font({ family: o.family || SERIF, size: o.size || 14, style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal' });
    t.fill(o.color || INK);
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
    return t;
  }
  function place(t, x, y, anchor) {
    var b = t.bbox();
    var dx = anchor === 'middle' ? -b.width / 2 : (anchor === 'end' ? -b.width : 0);
    t.move(x + dx, y - b.height / 2);
    return t;
  }

  /* ───────── static scenery ───────── */
  // axes
  stat.line(50, CYc, 570, CYc).stroke({ color: INK, width: 1.6 });
  tri(stat, 576, CYc, 1, 0, 12, INK);
  stat.line(CXc, 622, CXc, 24).stroke({ color: INK, width: 1.6 });
  tri(stat, CXc, 18, 0, -1, 12, INK);

  // unit circle: long solid arc + two dashed hints on the left
  var circ = stat.path(arcD(R, -150 * D2R, 150 * D2R)).fill('none')
    .stroke({ color: BLUE, width: 4.6, linecap: 'round' });
  stat.path(arcD(R, 158 * D2R, 175 * D2R)).fill('none').stroke({ color: BLUE, width: 4.6, linecap: 'round' });
  stat.path(arcD(R, -175 * D2R, -158 * D2R)).fill('none').stroke({ color: BLUE, width: 4.6, linecap: 'round' });
  circ.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Unit circle: the angle θ is carried to the point (cos θ, sin θ)', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The unit circle', 'Every real number θ is wrapped onto the circle of radius 1 at the point (cos θ, sin θ). Moving θ a little moves that point a little — that is the whole content of continuity for sine and cosine.');
    });

  // caption box
  var capBox = stat.rect(464, 86).move(68, 650).fill('#fff').stroke({ color: '#b3b3b3', width: 1.6 });
  place(T(stat, function (add) {
    add.tspan('As '); add.tspan('x').font({ 'font-style': 'italic' }); add.tspan(' approaches ');
    add.tspan('c').font({ 'font-style': 'italic' }); add.tspan(' the point');
  }, { size: 19 }), 300, 678, 'middle');
  place(T(stat, function (add) {
    add.tspan('P').font({ 'font-style': 'italic' }); add.tspan(' approaches the point ');
    add.tspan('Q').font({ 'font-style': 'italic' }); add.tspan('.');
  }, { size: 19 }), 300, 708, 'middle');
  capBox.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Key insight — click to read', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Why sine and cosine are continuous',
        'Continuity of sine and cosine is nothing more than the geometric fact that nearby angles put you at nearby points on the circle. "P → Q" is literally the pair of statements cos x → cos c and sin x → sin c, and since c was an arbitrary angle, both functions are continuous at every real number.');
    });

  // readout frame
  stat.rect(192, 132).move(398, 390).fill('#fcfcfd').stroke({ color: '#d5d8dc', width: 1.2 }).radius(4);
  place(T(stat, 'values', { size: 11, color: '#8a8f95', family: MONO }), 408, 401, 'start');

  /* ───────── state ───────── */
  var state = { x: 0.5, c: 1.15, approach: 'idle', coords: false };
  var rafId = 0, timerId = 0;

  function render() {
    dyn.clear();
    var x = state.x, c = state.c;
    var P = PT(x, R), Q = PT(c, R);
    var a0 = Math.min(x, c), a1 = Math.max(x, c);

    // sector
    if (a1 - a0 > 0.0015) {
      var A = PT(a0, R), B = PT(a1, R);
      var sec = dyn.path('M' + CXc + ' ' + CYc + ' L' + fp(A) + ' A' + R + ' ' + R + ' 0 0 0 ' + fp(B) + ' Z')
        .fill(grad).opacity(0.92).stroke('none');
      sec.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('Angular gap |x − c| = ' + Math.abs(x - c).toFixed(3) +
            ' rad · chord |PQ| = ' + Math.hypot(P[0] - Q[0], P[1] - Q[1]).toFixed(1) / R * 1 + '', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The shrinking wedge', 'The shaded sector is bounded by the two radii OP and OQ. Its opening angle is exactly |x − c|. Letting x → c collapses the wedge to a single ray, which forces P onto Q.');
        });
    }

    // coordinate projections
    if (state.coords) {
      var dash = { color: GRAY, width: 1.1, dasharray: '4,4' };
      dyn.line(P[0], P[1], P[0], CYc).stroke(dash);
      dyn.line(P[0], P[1], CXc, P[1]).stroke(dash);
      dyn.line(Q[0], Q[1], Q[0], CYc).stroke(dash);
      dyn.line(Q[0], Q[1], CXc, Q[1]).stroke(dash);
      dyn.line(Q[0], CYc - 6, Q[0], CYc + 6).stroke({ color: BLUE, width: 2.4 });
      dyn.line(CXc - 6, Q[1], CXc + 6, Q[1]).stroke({ color: BLUE, width: 2.4 });
      dyn.line(P[0], CYc - 6, P[0], CYc + 6).stroke({ color: RED, width: 2.4 });
      dyn.line(CXc - 6, P[1], CXc + 6, P[1]).stroke({ color: RED, width: 2.4 });

      var closeX = Math.abs(P[0] - Q[0]) < 48;
      place(T(dyn, 'cos x', { size: 12, italic: true, color: RED, halo: 3 }), P[0], CYc + 20, 'middle');
      place(T(dyn, 'cos c', { size: 12, italic: true, color: BLUE, halo: 3 }), Q[0], CYc + (closeX ? 40 : 20), 'middle');
      var closeY = Math.abs(P[1] - Q[1]) < 22;
      place(T(dyn, 'sin x', { size: 12, italic: true, color: RED, halo: 3 }), CXc - 14, P[1], 'end');
      place(T(dyn, 'sin c', { size: 12, italic: true, color: BLUE, halo: 3 }), CXc - (closeY ? 70 : 14), Q[1], 'end');
    }

    // radii
    dyn.line(CXc, CYc, Q[0], Q[1]).stroke({ color: INK, width: 1.7, linecap: 'round' });
    dyn.line(CXc, CYc, P[0], P[1]).stroke({ color: RED, width: 2.2, linecap: 'round' });

    // angle arcs
    if (x > 0.06) {
      dyn.path(arcD(48, 0, x)).fill('none').stroke({ color: INK, width: 1.2 });
      var e1 = PT(x, 48);
      tri(dyn, e1[0], e1[1], -Math.sin(x), -Math.cos(x), 9, INK);
    }
    if (c > 0.06) {
      dyn.path(arcD(88, 0, c)).fill('none').stroke({ color: INK, width: 1.2 });
    }
    var lx = PT(Math.max(0.12, x * 0.45), 64);
    place(T(dyn, 'x', { size: 19, italic: true, halo: 3.5 }), lx[0], lx[1], 'middle');
    var angC = (c - x > 0.32) ? (x + c) / 2 : c * 0.72;
    var lc = PT(angC, 104);
    place(T(dyn, 'c', { size: 19, italic: true, halo: 3.5 }), lc[0], lc[1], 'middle');

    // curved motion arrow P → Q
    if (Math.abs(c - x) > 0.14) {
      var s = PT(x, R + 34), en = PT(c, R + 26), m = PT((x + c) / 2, R + 78);
      dyn.path('M' + fp(s) + ' Q' + fp(m) + ' ' + fp(en)).fill('none')
        .stroke({ color: INK, width: 2, linecap: 'round' });
      tri(dyn, en[0], en[1], en[0] - m[0], en[1] - m[1], 12, INK);
    }

    // points
    var qd = dyn.circle(13).center(Q[0], Q[1]).fill(BLUE).stroke({ color: '#fff', width: 1.6 });
    var pd = dyn.circle(13).center(P[0], P[1]).fill(RED).stroke({ color: '#fff', width: 1.6 });
    pd.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('P = (cos ' + x.toFixed(3) + ', sin ' + x.toFixed(3) + ') = (' + Math.cos(x).toFixed(3) + ', ' + Math.sin(x).toFixed(3) + ')', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('The moving point P', 'P is the image of the variable angle x on the unit circle. Its two coordinates are exactly cos x and sin x, so watching P move is watching both functions change at once.'); });
    qd.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Q = (cos ' + c.toFixed(3) + ', sin ' + c.toFixed(3) + ') = (' + Math.cos(c).toFixed(3) + ', ' + Math.sin(c).toFixed(3) + ')', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('The target point Q', 'Q is the fixed point at the angle c — it is the function value. The limit claim is that P can be forced as close to Q as we like simply by taking x close enough to c.'); });

    // labels for P and Q
    var labPx = Math.min(P[0] + 24, 430), labPy = P[1] + 4;
    var labQx = Math.min(Q[0] + 26, 420), labQy = Q[1] - 28;
    if (Math.abs(labPy - labQy) < 26) labPy = (x > c) ? labQy - 30 : labQy + 30;
    var tQ = T(dyn, function (add) {
      add.tspan('Q').font({ 'font-style': 'italic' }); add.tspan('(cos ');
      add.tspan('c').font({ 'font-style': 'italic' }); add.tspan(', sin ');
      add.tspan('c').font({ 'font-style': 'italic' }); add.tspan(')');
    }, { size: 19, halo: 4 });
    place(tQ, labQx, labQy, 'start');
    var tP = T(dyn, function (add) {
      add.tspan('P').font({ 'font-style': 'italic' }); add.tspan('(cos ');
      add.tspan('x').font({ 'font-style': 'italic' }); add.tspan(', sin ');
      add.tspan('x').font({ 'font-style': 'italic' }); add.tspan(')');
    }, { size: 19, halo: 4 });
    place(tP, labPx, labPy, 'start');
    if (Math.abs(labPy - (P[1] + 4)) > 6) dyn.line(P[0] + 8, P[1], labPx - 4, labPy).stroke({ color: '#888', width: 0.9 });
    if (Math.abs(labQy - (Q[1] - 28)) > 6 || labQx - Q[0] > 30) dyn.line(Q[0] + 6, Q[1] - 4, labQx - 4, labQy + 6).stroke({ color: '#888', width: 0.9 });

    // readout
    var gap = Math.abs(x - c);
    var rows = [
      [['x = ' + x.toFixed(3), RED], ['c = ' + c.toFixed(3), BLUE]],
      [['cos x = ' + Math.cos(x).toFixed(3), RED], ['cos c = ' + Math.cos(c).toFixed(3), BLUE]],
      [['sin x = ' + Math.sin(x).toFixed(3), RED], ['sin c = ' + Math.sin(c).toFixed(3), BLUE]]
    ];
    var ys = [418, 440, 462];
    for (var i = 0; i < rows.length; i++) {
      place(T(dyn, rows[i][0][0], { size: 12, family: MONO, color: rows[i][0][1] }), 408, ys[i], 'start');
      place(T(dyn, rows[i][1][0], { size: 12, family: MONO, color: rows[i][1][1] }), 502, ys[i], 'start');
    }
    place(T(dyn, '|x − c| = ' + gap.toFixed(3), { size: 12.5, family: MONO, color: gap < 0.05 ? '#1a8a4a' : '#333', weight: 'bold' }), 408, 490, 'start');
    place(T(dyn, gap < 0.05 ? 'P is essentially at Q' : 'P still short of Q',
      { size: 11, family: MONO, color: gap < 0.05 ? '#1a8a4a' : '#8a8f95' }), 408, 508, 'start');
  }

  /* ───────── animation ───────── */
  function stopAnim() { cancelAnimationFrame(rafId); clearTimeout(timerId); }
  function setX(v) {
    v = Math.max(0, Math.min(3.14159, v));
    state.x = v;
    var inp = document.getElementById('angleXInput');
    var out = document.getElementById('angleXVal');
    if (inp) inp.value = v;
    if (out) out.value = v.toFixed(3);
    render();
  }
  function animateX(from, to, dur, done) {
    var t0 = performance.now();
    function tick(now) {
      var u = Math.min(1, (now - t0) / dur);
      var e = 1 - Math.pow(1 - u, 3);
      setX(from + (to - from) * e);
      if (u < 1) rafId = requestAnimationFrame(tick); else if (done) done();
    }
    rafId = requestAnimationFrame(tick);
  }
  function startApproach(mode) {
    stopAnim();
    if (mode === 'idle') return;
    var phases = mode === 'from left' ? ['L'] : (mode === 'from right' ? ['R'] : ['L', 'R']);
    var i = 0;
    function next() {
      var ph = phases[i % phases.length]; i++;
      var c = state.c, from, to;
      if (ph === 'L') { from = Math.max(0.01, c - 0.8); to = c - 0.012; }
      else { from = Math.min(3.1415, c + 0.8); to = Math.min(3.1415, c + 0.012); }
      if (Math.abs(from - to) < 0.04) { timerId = setTimeout(next, 200); return; }
      setX(from);
      timerId = setTimeout(function () {
        animateX(from, to, 2400, function () { timerId = setTimeout(next, 950); });
      }, 350);
    }
    next();
  }
  var MODES = ['idle', 'from left', 'from right', 'both sides'];
  function setApproachMode(mode, run) {
    state.approach = mode;
    var b = document.getElementById('approachInput');
    if (b) { b.textContent = 'Approach c: ' + mode; b.className = (mode === 'idle') ? '' : 'active'; }
    stopAnim();
    if (run && mode !== 'idle') startApproach(mode);
  }

  /* ───────── control handlers ───────── */
  window.update_angleX = function (v) { setApproachMode('idle', false); state.x = +v; render(); };
  window.update_angleC = function (v) {
    state.c = +v;
    render();
    if (state.approach !== 'idle') startApproach(state.approach);
  };
  window.trigger_approach = function () {
    var i = (MODES.indexOf(state.approach) + 1) % MODES.length;
    setApproachMode(MODES[i], true);
  };
  window.toggle_showCoords = function (on) { state.coords = !!on; render(); };

  /* ───────── demo steps ───────── */
  var steps = [
    { title: 'The setup', narration: 'Q sits at the fixed angle c on the unit circle; P sits at the variable angle x. The shaded sector between the two radii measures how far apart they are.', state: { angleC: 1.15, angleX: 0.5, approach: 'idle', showCoords: 'off' } },
    { title: 'Slide x toward c', narration: 'Drag x upward and watch P climb the arc toward Q — the sector narrows and the arc between the points shortens.', state: { angleC: 1.15, angleX: 1.0, approach: 'idle', showCoords: 'off' } },
    { title: 'Reading the coordinates', narration: "Turn on the projections: P's shadow on the x-axis is cos x and on the y-axis is sin x. As P nears Q, each shadow slides toward cos c and sin c.", state: { angleC: 1.15, angleX: 1.08, approach: 'idle', showCoords: 'on' } },
    { title: 'Approach from the left', narration: 'Let x increase up to c. P creeps along the arc and the sector shrinks to nothing — cos x → cos c and sin x → sin c from below.', state: { angleC: 1.15, angleX: 1.14, approach: 'from left', showCoords: 'on' } },
    { title: 'Approach from the right', narration: 'Now start past c and come back down. P arrives at the same point Q, so the one-sided limits agree.', state: { angleC: 1.15, angleX: 1.6, approach: 'from right', showCoords: 'on' } },
    { title: 'Any c at all', narration: 'Move Q to a different angle and repeat: the same collapse happens. Since c was arbitrary, sine and cosine are continuous at every real number.', state: { angleC: 2.4, angleX: 1.8, approach: 'both sides', showCoords: 'on' } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    stopAnim();
    // c
    state.c = s.state.angleC;
    var ic = document.getElementById('angleCInput'), oc = document.getElementById('angleCVal');
    if (ic) ic.value = state.c; if (oc) oc.value = state.c.toFixed(3);
    // coords
    state.coords = (s.state.showCoords === 'on');
    var cb = document.getElementById('showCoordsInput'); if (cb) cb.checked = state.coords;
    // x
    setX(s.state.angleX);
    // approach last
    setApproachMode(s.state.approach, true);
    var n = document.getElementById('demoNarration');
    if (n) n.textContent = s.title + ' — ' + s.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  render();
  window.__markRendered();
})();
// @FIGURE_CODE_END

