  function fp(p) { return p[0].toFixed(2) + ' ' + p[1].toFixed(2); }
  function arcD(r, a0, a1) {
    var A = PT(a0, r), B = PT(a1, r);
    var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
