    var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var px = -dy, py = dx;
    var pts = [[x, y],
    [x - dx * s + px * s * 0.42, y - dy * s + py * s * 0.42],
    [x - dx * s - px * s * 0.42, y - dy * s - py * s * 0.42]];
    return g.polygon(pts.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '))
      .fill(color).stroke('none');
  }
  function T(g, content, o) {
    o = o || {};
    var t = g.text(content);
    t.font({ family: o.family || SERIF, size: o.size || 14, style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal' });
    t.fill(o.color || INK);
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
    return t;
  }
