    { title: 'Any c at all', narration: 'Move Q to a different angle and repeat: the same collapse happens. Since c was arbitrary, sine and cosine are continuous at every real number.', state: { angleC: 2.4, angleX: 1.8, approach: 'both sides', showCoords: 'on' } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    stopAnim();
    state.c = s.state.angleC;
    var ic = document.getElementById('angleCInput'), oc = document.getElementById('angleCVal');
    if (ic) ic.value = state.c;
    if (oc) oc.value = state.c.toFixed(3);
    state.coords = (s.state.showCoords === 'on');
    var cb = document.getElementById('showCoordsInput'); if (cb) cb.checked = state.coords;
    setX(s.state.angleX);
    setApproachMode(s.state.approach, true);
    var n = document.getElementById('demoNarration');
    if (n) n.textContent = s.title + ' — ' + s.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  render();
  window.__markRendered();
})();
