// @FIGURE_CODE_BEGIN
(function () {
  var CW = 640, CH = 800;
  var CXc = 238, CYc = 348, R = 216;
  var BLUE = '#2ea7dd', RED = '#e8484c', INK = '#111', GRAY = '#9aa0a6';
  var SERIF = 'Georgia, "Times New Roman", serif';
  var D2R = Math.PI / 180;

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, CW, CH);

  // purple → white wedge fill (matches the textbook's gradient)
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#a462c6');
    add.stop(0.42, '#c896de');
    add.stop(1, '#fbf6fd');
  });
  try { grad.from(0.05, 0.9).to(0.95, 0.12); } catch (e) { }

  var stat = draw.group();
  var dyn = draw.group();

  function PT(a, r) { return [CXc + r * Math.cos(a), CYc - r * Math.sin(a)]; }
  function fp(p) { return p[0].toFixed(2) + ' ' + p[1].toFixed(2); }
  function arcD(r, a0, a1) {
    var A = PT(a0, r), B = PT(a1, r);
    var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
    var sweep = a1 > a0 ? 0 : 1;
    return 'M' + fp(A) + ' A' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + fp(B);
  }
  function tri(g, x, y, dx, dy, s, color) {
    var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var px = -dy, py = dx;
    var pts = [[x, y],
    [x - dx * s + px * s * 0.42, y - dy * s + py * s * 0.42],
    [x - dx * s - px * s * 0.42, y - dy * s - py * s * 0.42]];
    return g.polygon(pts.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '))
      .fill(color).stroke('none');
  }
  function T(g, content, o) {
    o = o || {};
    var t = g.text(content);
    t.font({ family: o.family || SERIF, size: o.size || 14, style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal' });
    t.fill(o.color || INK);
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
    return t;
  }
  function place(t, x, y, anchor) {
    var b = t.bbox();
    var dx = anchor === 'middle' ? -b.width / 2 : (anchor === 'end' ? -b.width : 0);
    t.move(x + dx, y - b.height / 2);
    // keep inside the canvas
