    if (nb.x < 6) t.dx(6 - nb.x);
    else if (nb.x + nb.width > CW - 6) t.dx((CW - 6) - (nb.x + nb.width));
    return t;
  }
  function anchorPoint(t) { var b = t.bbox(); return [b.x, b.y + b.height / 2]; }

  /* ───────── static scenery ───────── */
  stat.line(16, CYc, 600, CYc).stroke({ color: INK, width: 1.7 });
  tri(stat, 612, CYc, 1, 0, 14, INK);
  stat.line(CXc, 678, CXc, 40).stroke({ color: INK, width: 1.7 });
  tri(stat, CXc, 28, 0, -1, 14, INK);

  // unit circle: long solid arc + one clearly separated long dash on each
  // side of the left break (the "circle continues" convention)
  var circ = stat.path(arcD(R, -142 * D2R, 142 * D2R)).fill('none')
    .stroke({ color: BLUE, width: 5.5, linecap: 'round' });
  stat.path(arcD(R, 151 * D2R, 173 * D2R)).fill('none')
    .stroke({ color: BLUE, width: 5.5, linecap: 'round' });
  stat.path(arcD(R, -173 * D2R, -151 * D2R)).fill('none')
    .stroke({ color: BLUE, width: 5.5, linecap: 'round' });
  circ.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Unit circle: the angle θ is carried to the point (cos θ, sin θ)', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The unit circle', 'Every real number θ is wrapped onto the circle of radius 1 at the point (cos θ, sin θ). Moving θ a little moves that point a little — that is the whole content of continuity for sine and cosine.');
    });

  // caption box
  var capBox = stat.rect(478, 92).move(78, 694).fill('#fff').stroke({ color: '#b3b3b3', width: 1.7 });
  place(T(stat, function (add) {
    add.tspan('As '); add.tspan('x').font({ 'font-style': 'italic' }); add.tspan(' approaches ');
    add.tspan('c').font({ 'font-style': 'italic' }); add.tspan(' the point');
  }, { size: 21 }), 317, 722, 'middle');
  place(T(stat, function (add) {
    add.tspan('P').font({ 'font-style': 'italic' }); add.tspan(' approaches the point ');
    add.tspan('Q').font({ 'font-style': 'italic' }); add.tspan('.');
  }, { size: 21 }), 317, 756, 'middle');
  capBox.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Key insight — click to read', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Why sine and cosine are continuous',
        'Continuity of sine and cosine is nothing more than the geometric fact that nearby angles put you at nearby points on the circle. "P → Q" is literally the pair of statements cos x → cos c and sin x → sin c, and since c was an arbitrary angle, both functions are continuous at every real number.');
    });

  /* ───────── state ───────── */
  var state = { x: 0.5, c: 1.15, approach: 'idle', coords: false };
  var rafId = 0, timerId = 0;

  function setTxt(id, v) { var e = document.getElementById(id); if (e) e.textContent = v; }

  function updateReadout() {
