            ' rad  ·  chord PQ = ' + (2 * Math.sin(gap / 2)).toFixed(3) + ' (radii)', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The shrinking wedge', 'The shaded sector is bounded by the two radii OP and OQ, so its opening angle is exactly |x − c|. Letting x → c collapses the wedge to a single ray, which forces P onto Q.');
        });

      // emphasised blue arc along the sector's outer edge, from P to Q
      var hl = dyn.path(arcD(R, a0, a1)).fill('none')
        .stroke({ color: BLUE, width: 7, linecap: 'round' });
      hl.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('Arc PQ has length |x − c| = ' + Math.abs(x - c).toFixed(3) + ' (radii)', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Arc length = angle difference', 'On the unit circle the arc from P to Q measures exactly |x − c| radians, and the straight chord PQ is never longer than that arc. So the distance from P to Q is at most |x − c| — squeeze x toward c and P is squeezed onto Q.');
        });
    }

    // coordinate projections
    if (state.coords) {
      var dash = { color: GRAY, width: 1.1, dasharray: '4,4' };
      dyn.line(P[0], P[1], P[0], CYc).stroke(dash);
      dyn.line(P[0], P[1], CXc, P[1]).stroke(dash);
      dyn.line(Q[0], Q[1], Q[0], CYc).stroke(dash);
      dyn.line(Q[0], Q[1], CXc, Q[1]).stroke(dash);
      dyn.line(Q[0], CYc - 7, Q[0], CYc + 7).stroke({ color: BLUE, width: 2.6 });
      dyn.line(CXc - 7, Q[1], CXc + 7, Q[1]).stroke({ color: BLUE, width: 2.6 });
      dyn.line(P[0], CYc - 7, P[0], CYc + 7).stroke({ color: RED, width: 2.6 });
      dyn.line(CXc - 7, P[1], CXc + 7, P[1]).stroke({ color: RED, width: 2.6 });

      var closeX = Math.abs(P[0] - Q[0]) < 54;
      place(T(dyn, 'cos x', { size: 13, italic: true, color: RED, halo: 3.5 }), P[0], CYc + 20, 'middle');
      place(T(dyn, 'cos c', { size: 13, italic: true, color: BLUE, halo: 3.5 }), Q[0], CYc + (closeX ? 42 : 20), 'middle');
      var closeY = Math.abs(P[1] - Q[1]) < 24;
      place(T(dyn, 'sin x', { size: 13, italic: true, color: RED, halo: 3.5 }), CXc - 14, P[1], 'end');
      place(T(dyn, 'sin c', { size: 13, italic: true, color: BLUE, halo: 3.5 }), CXc - (closeY ? 74 : 14), Q[1], 'end');
    }

    // radii
    dyn.line(CXc, CYc, Q[0], Q[1]).stroke({ color: INK, width: 1.8, linecap: 'round' });
    dyn.line(CXc, CYc, P[0], P[1]).stroke({ color: RED, width: 2.3, linecap: 'round' });

    // angle arcs
