    place(T(dyn, 'x', { size: 21, italic: true, halo: 3.5 }), lx[0], lx[1], 'middle');
    var angC = (c - x > 0.34) ? (x + c) / 2 : c * 0.70;
    var lc = PT(angC, 132);
    place(T(dyn, 'c', { size: 21, italic: true, halo: 3.5 }), lc[0], lc[1], 'middle');

