    pd.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('P = (cos ' + x.toFixed(3) + ', sin ' + x.toFixed(3) + ') = (' + Math.cos(x).toFixed(3) + ', ' + Math.sin(x).toFixed(3) + ')', e); })
      .on('mouseleave', hideTooltip)
