      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('The target point Q', 'Q is the fixed point at the angle c — it is the function value. The limit claim is that P can be forced as close to Q as we like simply by taking x close enough to c.'); });

    // label text (drawn last, leaders inserted behind afterwards)
    var tQ = T(dyn, function (add) {
      add.tspan('Q').font({ 'font-style': 'italic' }); add.tspan('(cos ');
