      add.tspan('c').font({ 'font-style': 'italic' }); add.tspan(')');
    }, { size: 20, halo: 5 });
    place(tQ, labQx, labQy, 'start');
    var tP = T(dyn, function (add) {
      add.tspan('P').font({ 'font-style': 'italic' }); add.tspan('(cos ');
      add.tspan('x').font({ 'font-style': 'italic' }); add.tspan(', sin ');
      add.tspan('x').font({ 'font-style': 'italic' }); add.tspan(')');
    }, { size: 20, halo: 5 });
    place(tP, labPx, labPy, 'start');

    // short leaders when a label sits away from its dot
    var aq = anchorPoint(tQ), ap = anchorPoint(tP);
    if (Math.hypot(aq[0] - Q[0], aq[1] - Q[1]) > 40) {
